#!/usr/bin/env bash
# Applies חיברתי's customizations to the Android project generated by `npx cap add android`:
# icons, the Hebrew name, the app's own Java code (android-native/: Wi-Fi Direct, encrypted connection, files,
# screen sharing), permissions, the background service, the full-screen viewer, chibarti:// links, signing.
set -euo pipefail

RUN="${GITHUB_RUN_NUMBER:-1}"
VERSION="${APP_VERSION:-1.0}"
APP=android/app
RES=$APP/src/main/res
MAN=$APP/src/main/AndroidManifest.xml

# 1) Icons, splash and the status-bar icon
find "$RES" -name 'splash.png' -delete
cp -R android-res/. "$RES/"

# 2) App name in Hebrew (the label under the icon)
STR=$RES/values/strings.xml
perl -0pi -e 's|<string name="app_name">[^<]*</string>|<string name="app_name">חיברתי</string>|; s|<string name="title_activity_main">[^<]*</string>|<string name="title_activity_main">חיברתי</string>|' "$STR"

# 3) The app's Java code: MainActivity + plugin, connection, transfers, screen sharing, viewer, service
MAIN=$(find "$APP/src/main/java" -name MainActivity.java | head -1)
DIR=$(dirname "$MAIN")
PKG=$(sed -n 's/^package \(.*\);/\1/p' "$MAIN")
[ "$PKG" = "com.luachsport.chibarti" ] || { echo "unexpected package $PKG"; exit 1; }
cp android-native/*.java "$DIR/"

# chibarti://join links (a QR scanned with the phone's own camera opens the app and connects)
perl -0pi -e 's|(<activity\b[^>]*android:name="\.MainActivity"[^>]*>)|$1\n            <intent-filter>\n                <action android:name="android.intent.action.VIEW" />\n                <category android:name="android.intent.category.DEFAULT" />\n                <category android:name="android.intent.category.BROWSABLE" />\n                <data android:scheme="chibarti" android:host="join" />\n            </intent-filter>|s' "$MAN"
grep -q 'android:scheme="chibarti"' "$MAN" || { echo "deep link not added"; exit 1; }

perl -0pi -e 's|</application>|        <service android:name=".LinkService" android:exported="false" android:foregroundServiceType="connectedDevice\|mediaProjection" />\n        <service android:name=".ControlService" android:exported="true" android:label="\@string\/control_label" android:permission="android.permission.BIND_ACCESSIBILITY_SERVICE">\n            <intent-filter><action android:name="android.accessibilityservice.AccessibilityService" \/><\/intent-filter>\n            <meta-data android:name="android.accessibilityservice" android:resource="\@xml\/chibarti_control" \/>\n        <\/service>\n        <activity android:name=".ViewerActivity" android:exported="false" android:launchMode="singleTop" android:screenOrientation="fullUser" android:configChanges="orientation\|screenSize\|screenLayout\|smallestScreenSize\|keyboardHidden\|density" android:theme="\@android:style/Theme.Black.NoTitleBar.Fullscreen" android:excludeFromRecents="true" />\n    </application>|' "$MAN"

grep -q 'ControlService' "$MAN" || { echo "control service not added"; exit 1; }

PERMS='    <uses-permission android:name="android.permission.ACCESS_NETWORK_STATE" />
    <uses-permission android:name="android.permission.CHANGE_NETWORK_STATE" />
    <uses-permission android:name="android.permission.ACCESS_WIFI_STATE" />
    <uses-permission android:name="android.permission.CHANGE_WIFI_STATE" />
    <uses-permission android:name="android.permission.CHANGE_WIFI_MULTICAST_STATE" />
    <uses-permission android:name="android.permission.ACCESS_FINE_LOCATION" android:maxSdkVersion="32" />
    <uses-permission android:name="android.permission.ACCESS_COARSE_LOCATION" android:maxSdkVersion="32" />
    <uses-permission android:name="android.permission.NEARBY_WIFI_DEVICES" android:usesPermissionFlags="neverForLocation" />
    <uses-permission android:name="android.permission.FOREGROUND_SERVICE" />
    <uses-permission android:name="android.permission.FOREGROUND_SERVICE_CONNECTED_DEVICE" />
    <uses-permission android:name="android.permission.FOREGROUND_SERVICE_MEDIA_PROJECTION" />
    <uses-permission android:name="android.permission.POST_NOTIFICATIONS" />
    <uses-permission android:name="android.permission.WAKE_LOCK" />
    <uses-permission android:name="android.permission.VIBRATE" />
    <uses-permission android:name="android.permission.RECORD_AUDIO" />
    <uses-permission android:name="android.permission.CAMERA" />
    <uses-permission android:name="android.permission.WRITE_EXTERNAL_STORAGE" android:maxSdkVersion="28" />
    <uses-feature android:name="android.hardware.wifi.direct" android:required="false" />
    <uses-feature android:name="android.hardware.wifi" android:required="false" />
    <uses-feature android:name="android.hardware.camera" android:required="false" />
    <uses-feature android:name="android.hardware.camera.autofocus" android:required="false" />
    <uses-feature android:name="android.hardware.microphone" android:required="false" />
    <uses-feature android:name="android.hardware.touchscreen" android:required="false" />'
PERMS="$PERMS" perl -0pi -e 's|</manifest>|$ENV{PERMS}\n</manifest>|' "$MAN"

# Android 6-9 save received files straight into Download/Pictures (legacy storage until Android 10)
perl -0pi -e 's|<application\b|<application android:requestLegacyExternalStorage="true"|' "$MAN"

# 4) Teal splash with the two phones on Android 12+
STY=$RES/values/styles.xml
perl -0pi -e 's|(<style name="AppTheme.NoActionBarLaunch" parent="Theme.SplashScreen">)|$1\n        <item name="windowSplashScreenBackground">#0A8F94</item>\n        <item name="windowSplashScreenAnimatedIcon">\@mipmap/ic_launcher_foreground</item>|' "$STY"

# 5) Android 6.0 and up (the oldest Capacitor 7 runs on); target SDK 34 (the app is installed directly, not from Play)
sed -i -E 's/minSdkVersion = [0-9]+/minSdkVersion = 23/; s/targetSdkVersion = [0-9]+/targetSdkVersion = 34/' android/variables.gradle

# 6) Version: name is the product version, code is the build number (so every APK installs as an update)
sed -i -E "s/versionCode [0-9]+/versionCode ${RUN}/; s/versionName \"[^\"]*\"/versionName \"${VERSION}\"/" "$APP/build.gradle"

# 7) Release signing with the permanent key (password from GitHub secrets)
cat >> "$APP/build.gradle" <<'GRADLE'

android {
    compileOptions {
        encoding "UTF-8"
    }
    signingConfigs {
        chibarti {
            storeFile file("release.jks")
            storePassword System.getenv("CHIBARTI_STORE_PASSWORD")
            keyAlias System.getenv("CHIBARTI_KEY_ALIAS")
            keyPassword System.getenv("CHIBARTI_KEY_PASSWORD")
        }
    }
    buildTypes {
        release {
            signingConfig signingConfigs.chibarti
            minifyEnabled false
        }
    }
    lint {
        abortOnError false
        checkReleaseBuilds false
    }
}
GRADLE

echo "--- manifest"; cat "$MAN"
echo "--- strings"; cat "$STR"
echo "--- java ($PKG)"; ls "$DIR"
echo "--- launch style"; grep -n -A3 'NoActionBarLaunch' "$STY"
echo "--- versions"; grep -n -E 'versionCode|versionName' "$APP/build.gradle"; grep -n -E 'targetSdk|minSdk' android/variables.gradle
